private fun symbol(name: String, autoMirror: Boolean, viewport: Float, vararg paths: String): ImageVector =
    ImageVector.Builder(
        name = "Symbols.$name",
        defaultWidth = 24.dp,
        defaultHeight = 24.dp,
        viewportWidth = viewport,
        viewportHeight = viewport,
        autoMirror = autoMirror,
    ).apply {
        paths.forEach { path ->
            addPath(PathParser().parsePathString(path).toNodes(), fill = SolidColor(Color.Black))
        }
    }.build()
